    }
};

class Student : public Person {
    int marks;
public:
    Student(string n, int m) : Person(n) {
        marks = m;
    }
    void show() {
        cout << "STUDENT " << name << " marks " << marks;
        if (marks >= 40) {
            cout << " grade PASS" << endl;
        } else {
            cout << " grade FAIL" << endl;
        }
    }
