class Professor : public Person {
    int papers;
public:
    Professor(string n, int p) : Person(n) {
        papers = p;
    }
    void show() {
        cout << "PROFESSOR " << name << " publications " << papers;
        if (papers >= 5) {
            cout << " status ACTIVE" << endl;
        } else {
            cout << " status RISING" << endl;
        }
    }
};

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string kind, name;
        int value;
        cin >> kind >> name >> value;
        if (kind == "student") {
            Student s(name, value);
            s.show();
        } else {
            Professor p(name, value);
            p.show();
        }
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Playable {
protected:
    int totalSeconds;
public:
    Playable() {
        totalSeconds = 0;
    }
    void addPlay(int seconds) {
        totalSeconds += seconds;
    }
    int playTime() {
        return totalSeconds;
    }
};

class Downloadable {
protected:
    int totalMb;
public:
    Downloadable() {
        totalMb = 0;
    }
    void addDownload(int mb) {
        totalMb += mb;
    }
    int dataSize() {
        return totalMb;
    }
};

class MediaLibrary : public Playable, public Downloadable {
public:
    void addItem(string kind, int seconds, int mb) {
        cout << kind << " queued: " << seconds << " sec, " << mb << " MB" << endl;
        addPlay(seconds);
        addDownload(mb);
    }
    void stats() {
        cout << "Total play time: " << playTime() << " seconds" << endl;
        cout << "Total download size: " << dataSize() << " MB" << endl;
    }
};

int main() {
    int n;
    cin >> n;
    MediaLibrary lib;
    for (int i = 0; i < n; i++) {
        string kind;
        int seconds, mb;
        cin >> kind >> seconds >> mb;
        lib.addItem(kind, seconds, mb);
    }
    lib.stats();
    return 0;
}

